    int kill = 0;

    if (getClientType(c) == CLIENT_TYPE_PUBSUB) {
        /* Check for pattern violations. */
        dictIterator *di = dictGetIterator(c->pubsub_data->pubsub_patterns);
        dictEntry *de;
